package com.example.lab15; import android.os.Bundle; import android.view.*; import android.widget.*; import androidx.appcompat.app.AlertDialog; import androidx.appcompat.app.AppCompatActivity;
public class MainActivity extends AppCompatActivity { int[] images={R.drawable.apple,R.drawable.pineapple,R.drawable.banana,R.drawable.strawberry,R.drawable.grapes,R.drawable.pear}; String[] names={"Apple","Pineapple","Banana","Strawberry","Grapes","Pear"}; @Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);GridView grid=findViewById(R.id.gridView);grid.setAdapter(new ImageAdapter());grid.setOnItemClickListener((parent,view,position,id)->new AlertDialog.Builder(MainActivity.this).setTitle("Selected Image").setMessage("You selected: "+names[position]).setPositiveButton("OK",null).show());}
 class ImageAdapter extends BaseAdapter { public int getCount(){return images.length;} public Object getItem(int p){return images[p];} public long getItemId(int p){return p;} public View getView(int p,View cv,ViewGroup parent){if(cv==null)cv=getLayoutInflater().inflate(R.layout.grid_item,parent,false);((ImageView)cv.findViewById(R.id.imageView)).setImageResource(images[p]);return cv;} } }